-- Disposable local tests ONLY. Never execute this file on hosted Supabase.
begin;
create function public.test_assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; raise notice 'PASS: %',label; end $$;
create function public.test_reject(command text,expected text[],label text) returns void language plpgsql as $$ declare rejected boolean:=false; begin begin execute command; exception when others then if sqlstate=any(expected) then rejected:=true;else raise;end if;end;if not rejected then raise exception 'FAILED: %',label;end if;raise notice 'PASS: %',label;end $$;
insert into public.organizations(id,name) values('10000000-0000-4000-8000-000000000001','Local test only');
insert into auth.users(id,email) values('20000000-0000-4000-8000-000000000001','driver@example.test'),('20000000-0000-4000-8000-000000000002','other-driver@example.test');
insert into public.staff_members(user_id,organization_id,email,display_name,role) select id,'10000000-0000-4000-8000-000000000001',email,'Local driver','driver' from auth.users;
insert into public.drivers(id,organization_id,name,phone,license_number,status,auth_user_id) values('30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Local driver','000','LOCAL','available','20000000-0000-4000-8000-000000000001');
insert into public.drivers(id,organization_id,name,phone,license_number,status,auth_user_id) values('30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','Other local driver','000','LOCAL-OTHER','available','20000000-0000-4000-8000-000000000002');
insert into public.customers(id,organization_id,name,phone) values('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Local customer','000');
insert into public.locations(id,organization_id,name,kind,address) values('50000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Local pickup','other','Local test'),('50000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','Local destination','other','Local test');
insert into public.vehicles(id,organization_id,name,plate_number,category,capacity,luggage_capacity,status) values('60000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Local vehicle','LOCAL','sedan',4,4,'available');
insert into public.bookings(id,organization_id,customer_id,pickup_location_id,dropoff_location_id,driver_id,vehicle_id,pickup_at,end_at,vehicle_category,passengers,luggage,status,price_aed,payment_status) values('70000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001',now(),now()+interval '1 hour','sedan',1,1,'pending',0,'unpaid');
update public.bookings set status='confirmed';
set local role authenticated;
set local request.jwt.claim.sub='20000000-0000-4000-8000-000000000002';
select public.test_assert(jsonb_array_length(public.driver_assigned_trips())=0,'another linked driver cannot read this assignment');
select public.test_reject($q$select public.driver_trip_action('70000000-0000-4000-8000-000000000001','accept')$q$,array['42501'],'other driver cannot change trip');
set local request.jwt.claim.sub='20000000-0000-4000-8000-000000000001';
select public.test_assert(jsonb_array_length(public.driver_assigned_trips())=1,'linked driver sees own assignment');
select public.test_assert((select count(*)=0 from public.bookings),'driver projection does not grant management table access');
reset role;
update public.drivers set account_status='inactive' where id='30000000-0000-4000-8000-000000000001';
set local role authenticated;
select public.test_reject($q$select public.driver_assigned_trips()$q$,array['42501'],'revoked driver session cannot read assignments');
reset role;
update public.drivers set account_status='active' where id='30000000-0000-4000-8000-000000000001';
set local role authenticated;
select public.test_reject($q$select public.driver_trip_action('70000000-0000-4000-8000-000000000001','pickup')$q$,array['P0001'],'pickup before arrival rejected');
select public.driver_trip_action('70000000-0000-4000-8000-000000000001','accept');
select public.test_reject($q$select public.driver_trip_action('70000000-0000-4000-8000-000000000001','accept')$q$,array['P0001'],'duplicate acceptance rejected');
select public.driver_trip_action('70000000-0000-4000-8000-000000000001','arrive');
select public.driver_trip_action('70000000-0000-4000-8000-000000000001','pickup');
select public.test_assert(public.driver_assigned_trips()->0->>'status'='in_progress','pickup follows real booking transition');
select public.driver_trip_action('70000000-0000-4000-8000-000000000001','complete');
select public.test_assert(jsonb_array_length(public.driver_assigned_trips())=0,'completed trips leave active driver assignments');
select public.test_reject($q$select public.driver_trip_action('70000000-0000-4000-8000-000000000001','complete')$q$,array['42501'],'terminal trip cannot be completed again');
reset role;
rollback;
